package io.github.ningpp.compat;

import java.util.concurrent.CompletableFuture;

/**
 * Mirrors the BCL {@code System.Collections.Generic.IAsyncEnumerator<T>}
 * interface for converted C# code (generated by CSharpToJava converter).
 * Extends {@link AsyncDisposable} exactly as the BCL interface extends
 * {@code System.IAsyncDisposable}.
 *
 * <p>Blocking model (C18 design §1.2 / C38 design §5): converted {@code await}
 * becomes {@link CompletableFuture#join()}. An {@code await foreach} driving
 * loop lowers to {@code while (((Boolean) enumerator.moveNextAsync().join()).booleanValue())}
 * — the future yields the boxed {@link Boolean} and the converter's existing
 * join-unboxing table emits the primitive unbox for the condition — and the
 * loop tail releases with {@code enumerator.disposeAsync().join();} in a
 * plain try/finally (the measured net10 truth: a dispose fault masks the
 * in-flight fault, SampleAsyncSolution T4 / AsyncStreamsBridgeTest).</p>
 *
 * @param <T> type of the enumerated elements
 */
public interface AsyncEnumerator<T> extends AsyncDisposable {

    /**
     * Mirrors {@code IAsyncEnumerator<T>.MoveNextAsync()} (BCL return type
     * {@code ValueTask<bool>}, mapped to {@code CompletableFuture<Boolean>}).
     *
     * @return a future yielding {@code true} while an element is available
     */
    CompletableFuture<Boolean> moveNextAsync();

    /**
     * Mirrors {@code IAsyncEnumerator<T>.Current}.
     *
     * @return the element at the current enumerator position
     */
    T getCurrent();
}
